+Value Value::Numeric(const LogicalType &type, hugeint_t value) {
+	switch (type.id()) {
+	case LogicalTypeId::HUGEINT:
+		return Value::HUGEINT(value);
+	default:
+		return Value::Numeric(type, Hugeint::Cast<int64_t>(value));
+	}
